import{c as s,J as c,h as d,k as l}from"./chunks/framework.NhpCCunm.js";const u=JSON.parse('{"title":"Статьи и руководства по экономике производства","description":"Практические руководства по экономике цеха, ценообразованию, формулам себестоимости и учёту для мастеров и малых производств.","frontmatter":{"title":"Статьи и руководства по экономике производства","description":"Практические руководства по экономике цеха, ценообразованию, формулам себестоимости и учёту для мастеров и малых производств."},"headers":[],"relativePath":"ru/articles/index.md","filePath":"ru/articles/index.md"}'),r={name:"ru/articles/index.md"};function e(t,a,i,n,o,p){return c(),d("div",null,[...a[0]||(a[0]=[l('<h1 id="статьи-и-руководства-по-экономике-производства" tabindex="-1">Статьи и руководства по экономике производства <a class="header-anchor" href="#статьи-и-руководства-по-экономике-производства" aria-label="Permalink to &quot;Статьи и руководства по экономике производства&quot;">​</a></h1><p>База прикладных знаний и экономических руководств для ремесленников, частных цехов и малых производств. Мы делимся реальным производственным опытом: без абстрактной теории, без академизма и без иллюзий о лёгких деньгах.</p><hr><div class="calc-promo-banner"><div class="promo-text-wrap"><div class="promo-badge">Интерактивные инструменты</div><div class="promo-title">Онлайн-калькуляторы себестоимости продукции</div><div class="promo-desc">7 готовых отраслевых калькуляторов с оцифровкой технологических потерь, брака, комплектующих и экспортом смет в Excel.</div></div><a href="/ru/calculators/" class="promo-btn">Все калькуляторы →</a></div><hr><h2 id="методологические-руководства-и-аналитика" tabindex="-1">Методологические руководства и аналитика <a class="header-anchor" href="#методологические-руководства-и-аналитика" aria-label="Permalink to &quot;Методологические руководства и аналитика&quot;">​</a></h2><div class="articles-feed"><div class="article-card featured-card"><div class="card-badges"><span class="badge-tag">Экономика</span><span class="badge-tag">Ценообразование</span><span class="badge-tag">Флагманский материал</span></div><div class="card-title"><a href="/ru/articles/pricing-and-margins"> Ценообразование, наценка и маржа: как рассчитать стоимость изделия и не работать в минус </a></div><p class="card-desc"> Разбираем принципиальную разницу между торговой наценкой и маржой: почему наценка в 40% даёт всего 28% маржинальности, как правильно рассчитать цену продажи от себестоимости и как определить точку безубыточности мастерской. Внутри статьи — интерактивный калькулятор маржинальности и наценки. </p><div class="card-footer"><span class="read-time">Интерактивный расчёт: ~5 минут</span><a href="/ru/articles/pricing-and-margins" class="card-link"> Читать руководство и рассчитать маржу → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Софт и учёт</span><span class="badge-tag">Автоматизация</span><span class="badge-tag">Мастерская</span></div><div class="card-title"><a href="/ru/articles/cost-calculation-software"> Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским </a></div><p class="card-desc"> Эволюция производственного учёта: от рукописного блокнота до таблиц Excel и корпоративных систем. Разбираем скрытые ошибки формул, проблему партионного списания сырья по скользящей средней (MAC) и ключевые требования к специализированному локальному софту. </p><div class="card-footer"><span class="read-time">Время чтения: ~7 минут</span><a href="/ru/articles/cost-calculation-software" class="card-link"> Читать статью → </a></div></div></div><hr><h2 id="отраслевые-разборы-экономики-и-технологических-потерь" tabindex="-1">Отраслевые разборы экономики и технологических потерь <a class="header-anchor" href="#отраслевые-разборы-экономики-и-технологических-потерь" aria-label="Permalink to &quot;Отраслевые разборы экономики и технологических потерь&quot;">​</a></h2><div class="articles-feed"><div class="article-card"><div class="card-badges"><span class="badge-tag">Кожевенное дело</span><span class="badge-tag">Технологические потери</span></div><div class="card-title"><a href="/ru/calculators/leather-cost-calculator"> Экономика кожевенной мастерской: ловушка краевых обрезков и формула стоимости изделия </a></div><p class="card-desc"> Разбираем две главные финансовые ловушки частного мастера: почему нельзя считать натуральную кожу по чистым геометрическим выкройкам, сколько денег улетает в обрезки под верстак (до 35%) и почему видимость заказов часто оборачивается работой «в ноль». </p><div class="card-footer"><span class="read-time">Время чтения: ~8 минут</span><a href="/ru/calculators/leather-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">3D-печать</span><span class="badge-tag">Инженерия</span></div><div class="card-title"><a href="/ru/calculators/3d-print-cost-calculator"> Экономика 3D-печати: потери на поддержки, калибровка и амортизация принтера </a></div><p class="card-desc"> Инженерный разбор для студий 3D-печати и мелкосерийного производства. Расчёт чистого веса филамента, потерь на поддержки и калибровку (15–20%), стоимости закладных латунных втулок M3, амортизации сопел и нормы-часа оператора. </p><div class="card-footer"><span class="read-time">Время чтения: ~7 минут</span><a href="/ru/calculators/3d-print-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Общепит и кулинария</span><span class="badge-tag">Фудкост</span></div><div class="card-title"><a href="/ru/calculators/dish-cost-calculator"> Экономика кулинарного цеха: технологическая карта, фудкост и процент термопотерь </a></div><p class="card-desc"> Методика составления технологической карты для шеф-поваров, кулинарных цехов и пельменных. Перевод брутто в нетто, термопотери на уварку и ужарку (до 35%), порционные специи, вакуумная упаковка и маркировка КБЖУ. </p><div class="card-footer"><span class="read-time">Время чтения: ~7 минут</span><a href="/ru/calculators/dish-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Кондитерское дело</span><span class="badge-tag">Упёк</span></div><div class="card-title"><a href="/ru/calculators/cake-cost-calculator"> Экономика кондитерской: расчёт сырьевого замеса, упёка коржей и высокой коробки </a></div><p class="card-desc"> Специализированный разбор для кондитеров и домашних пекарен: расчёт сырьевого замеса, коэффициента упёка в духовке (10–14%), стоимости крем-чиза, свежих ягод, усиленной подложки и картонной коробки. </p><div class="card-footer"><span class="read-time">Время чтения: ~7 минут</span><a href="/ru/calculators/cake-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Свечеварение</span><span class="badge-tag">Хэндмейд</span></div><div class="card-title"><a href="/ru/calculators/candle-cost-calculator"> Экономика свечеварения: плотность воска, ввод отдушек и остатки в питчере </a></div><p class="card-desc"> Практическое руководство для свечеваров и мыловаров. Расчёт плотности воска под объём банки (мл vs г), точного ввода премиальной отдушки (8–10%), деревянного фитиля, остатков в питчере и упаковки. </p><div class="card-footer"><span class="read-time">Время чтения: ~6 минут</span><a href="/ru/calculators/candle-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Бьюти-услуги</span><span class="badge-tag">Ногтевой сервис</span></div><div class="card-title"><a href="/ru/calculators/beauty-cost-calculator"> Экономика ногтевого сервиса: себестоимость процедуры, стерилизация и аренда </a></div><p class="card-desc"> Профессиональный разбор для мастеров ногтевого сервиса. Расчёт расхода базы и гель-лака на клиента, стоимости одноразового абразивного набора, стерилизации крафт-пакетов по СанПиН и почасовой аренды кабинета. </p><div class="card-footer"><span class="read-time">Время чтения: ~6 минут</span><a href="/ru/calculators/beauty-cost-calculator" class="card-link"> Читать разбор и калькулятор → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Базовая смета</span><span class="badge-tag">Все товары</span></div><div class="card-title"><a href="/ru/calculators/product-cost-calculator"> Универсальная смета изделия: оцифровка сырья, брака и нормы-часа </a></div><p class="card-desc"> Универсальный онлайн-калькулятор и методика расчёта себестоимости для мастеров, цехов и малых производств. Оцифровка сырья, технологических потерь, комплектующих, стоимости нормы-часа и амортизации оборудования с экспортом в Excel (.xlsx). </p><div class="card-footer"><span class="read-time">Время чтения: ~6 минут</span><a href="/ru/calculators/product-cost-calculator" class="card-link"> Читать статью и открыть калькулятор → </a></div></div></div>',10)])])}const g=s(r,[["render",e]]);export{u as __pageData,g as default};
